def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    day = day_context['day']
    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append((oid, opp))

    if not alive:
        return float(min(budget, DAILY_SALARY * 0.35))

    prev_bids = []
    danger_bids = []
    moderate_bids = []
    for oid, opp in alive:
        prev = opp.get('previous_trace', {})
        bid = prev.get('bid') if prev else None
        if bid is not None:
            prev_bids.append(float(bid))
            if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
                danger_bids.append(float(bid))
            else:
                moderate_bids.append(float(bid))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    highest_danger = max(danger_bids) if danger_bids else 0.0
    highest_moderate = max(moderate_bids) if moderate_bids else 0.0

    guaranteed_units = int(supply // WATER_REQ)
    tight_supply = guaranteed_units <= 1
    abundant_supply = guaranteed_units >= 2

    days_left = max(0, 10 - day)
    reserve_floor = max(0.0, days_left * DAILY_SALARY * 0.18)
    spendable = max(0.0, budget - reserve_floor)

    urgent = hp <= 3 or no_water_days >= 1
    semi_urgent = hp <= 5

    if urgent:
        target = max(DAILY_SALARY * 0.95, highest_prev + 2.0)
        if tight_supply:
            target = max(target, highest_danger + 2.5, highest_moderate + 1.5)
        bid = min(budget, target)
        return float(max(0.0, bid))

    if abundant_supply:
        base = DAILY_SALARY * 0.34
        if highest_prev > 0:
            base = max(base, min(highest_prev * 0.55, DAILY_SALARY * 0.62))
        bid = min(budget, min(spendable + DAILY_SALARY * 0.15, base))
        return float(max(0.0, bid))

    if semi_urgent:
        target = max(DAILY_SALARY * 0.72, highest_moderate + 1.5)
        if highest_danger > 0:
            target = max(target, highest_danger + 1.0)
        bid = min(budget, min(spendable + DAILY_SALARY * 0.35, target))
        return float(max(0.0, bid))

    if highest_prev >= DAILY_SALARY * 1.35:
        bid = min(budget, DAILY_SALARY * 0.28)
    elif highest_prev >= DAILY_SALARY * 1.0:
        bid = min(budget, DAILY_SALARY * 0.42)
    elif highest_prev >= DAILY_SALARY * 0.75:
        bid = min(budget, highest_prev * 0.78)
    elif highest_prev > 0:
        bid = min(budget, max(DAILY_SALARY * 0.48, highest_prev + 1.0))
    else:
        bid = min(budget, DAILY_SALARY * 0.5)

    if spendable < bid:
        bid = max(0.0, min(budget, spendable + DAILY_SALARY * 0.12))

    return float(max(0.0, bid))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        return min(my_status['budget'], 20.0)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    if yesterday_bids:
        max_prev = max(yesterday_bids)
        if my_status['hp'] < 4:
            return min(my_status['budget'], max_prev + 10.0)
        return min(my_status['budget'], max(30.0, max_prev * 0.8))

    return min(my_status['budget'], 40.0)
